    stream.avail_out = (uInt)bound;
    zret             = deflate(&stream, Z_FINISH);
    ck_assert_int_eq(zret, Z_STREAM_END);
    *output_length = (size_t)stream.total_out;
    ck_assert_int_eq(deflateEnd(&stream), Z_OK);
