    ck_assert_ptr_nonnull(map);
    map->need = rust_initial_read_failure;

    ctx.engine                = &engine;
    ctx.options               = &options;
    ctx.fmap                  = map;
    ctx.recursion_stack       = &layer;
    ctx.recursion_stack_size  = 1;
    layer.type                = CL_TYPE_LHA_LZH;
