    layer.fmap               = map;

    ret = cli_scanapm(&ctx);
    ck_assert_int_eq(ret, CL_EFORMAT);
    ck_assert(ctx.scan_incomplete);
    ck_assert_str_eq(ctx.scan_incomplete_reason, "APM partition entry is outside the declared partition table");
    ck_assert(map->dont_cache_flag);

