    zip_stream_write_u32(file_archive + offset, 0x08E28222U);
    offset += 4;
    zip_stream_write_u32(file_archive + offset, 0x0A8590E3U);
    offset += 4;
    zip_stream_write_u32(file_archive + offset, 1U);
    offset += 4;
    zip_stream_write_u64(file_archive + offset, 0U);
