static const void *fmap_gets_read_failure(fmap_t *map, char *dst, size_t *at, size_t max_len)
{
    (void)map;
    (void)dst;
    (void)at;
    (void)max_len;
    return NULL;
}

static const void *uuencode_attachment_read_failure(fmap_t *map, char *dst, size_t *at, size_t max_len)
{
    size_t start = *at;
    size_t len;
    const char *src;
    const char *end;

    if (start >= map->len || max_len == 0 || start == 18U || ((const uint8_t *)map->data)[start] == '#')
        return NULL;

    len = MIN(max_len - 1, map->len - start);
    src = (const char *)map->data + start;
    end = memchr(src, '\n', len);
    if (end != NULL)
        len = (size_t)(end - src) + 1;

    memcpy(dst, src, len);
    dst[len] = '\0';
    *at += len;
    return dst;
}

