    memcpy(sfx_data + SFX_PREFIX_SIZE, archive_data, archive_size);
    free(archive_data);

    memset(&options, 0, sizeof(options));
    options.parse = CL_SCAN_PARSE_ARCHIVE | CL_SCAN_PARSE_PE;
    ck_assert_int_eq(cl_init(CL_INIT_DEFAULT), CL_SUCCESS);
