    pe_icon_test_write_u32(data + 0x84, 4);

    pe_icon_test_write_u16(data + 0xa0 + 14, 1);
    pe_icon_test_write_u32(data + 0xb0, 1);
    pe_icon_test_write_u32(data + 0xb4, 0xc0U);
